<?php
/**
 * TrackWP_License tests.
 *
 * Producer: tests/fixtures/license/tokens.json and domain-vectors.json are
 * generated by license-server/scripts/gen-plugin-fixtures.js with the server's
 * own signToken() (license-server/src/token.js) and the TEST key; the test
 * public key is injected through the trackwp_license_public_keys filter only.
 */
class Test_TrackWP_License extends WP_UnitTestCase {

    private $fx;
    private $mock;

    private static function fixture( $file ) {
        return json_decode( file_get_contents( __DIR__ . '/fixtures/license/' . $file ), true );
    }

    private function token( $name ) {
        foreach ( $this->fx['cases'] as $c ) {
            if ( $c['name'] === $name ) {
                return $c['token'];
            }
        }
        $this->fail( 'no fixture ' . $name );
    }

    public function set_up() {
        parent::set_up();
        $this->fx = self::fixture( 'tokens.json' );
        TrackWP_License::force_state_for_tests( null );
        add_filter( 'trackwp_license_public_keys', array( $this, 'keys_filter' ) );
        add_filter( 'pre_option_home', array( $this, 'home_filter' ) );
        delete_option( TrackWP_License::OPTION );
        delete_option( TrackWP_License::GRACE_OPT );
    }

    public function tear_down() {
        remove_all_filters( 'pre_http_request' );
        remove_filter( 'trackwp_license_public_keys', array( $this, 'keys_filter' ) );
        remove_filter( 'pre_option_home', array( $this, 'home_filter' ) );
        TrackWP_License::force_state_for_tests( true );
        parent::tear_down();
    }

    public function keys_filter() {
        return array( $this->fx['kid'] => $this->fx['public_key'] );
    }

    public function home_filter() {
        return 'https://www.example.dk';
    }

    private function store( $token, $key = 'TWP-TEST' ) {
        update_option(
            TrackWP_License::OPTION,
            array(
                'key'          => TrackWP_Hash::encode( $key ),
                'token'        => $token,
                'last_error'   => '',
                'last_attempt' => 0,
            )
        );
    }

    private function mock_http( $response ) {
        $this->mock = 0;
        remove_all_filters( 'pre_http_request' );
        add_filter(
            'pre_http_request',
            function () use ( $response ) {
                $this->mock++;
                return $response;
            }
        );
    }

    private static function http( $code, $body ) {
        return array(
            'response' => array( 'code' => $code, 'message' => '' ),
            'body'     => $body,
            'headers'  => array(),
            'cookies'  => array(),
            'filename' => null,
        );
    }

    private function token_answer( $name ) {
        return self::http( 200, wp_json_encode( array( 'token' => $this->token( $name ) ) ) );
    }

    // --- verify_token ------------------------------------------------

    public function test_verify_token_matches_every_server_fixture() {
        $keys = array( $this->fx['kid'] => $this->fx['public_key'] );
        foreach ( $this->fx['cases'] as $c ) {
            $r = TrackWP_License::verify_token( $c['token'], $keys, $c['host'] );
            $this->assertSame( $c['expect']['ok'], $r['ok'], $c['name'] );
            if ( $c['expect']['ok'] ) {
                $this->assertSame( $c['expect']['status'], $r['status'], $c['name'] );
                $this->assertSame( $c['expect']['exp'], $r['exp'], $c['name'] );
                $this->assertSame( $c['expect']['lexp'], $r['lexp'], $c['name'] );
            } else {
                $this->assertSame( $c['expect']['reason'], $r['reason'], $c['name'] );
            }
        }
    }

    public function test_production_key_list_does_not_verify_test_tokens() {
        $r = TrackWP_License::verify_token( $this->token( 'active' ), TrackWP_License::PUBLIC_KEYS, 'example.dk' );
        $this->assertFalse( $r['ok'] );
        $this->assertNotContains( $this->fx['public_key'], TrackWP_License::PUBLIC_KEYS );
    }

    // --- normalize_host ----------------------------------------------

    public function test_normalize_host_matches_all_server_vectors() {
        $v = self::fixture( 'domain-vectors.json' );
        $this->assertNotEmpty( $v['cases'] );
        foreach ( $v['cases'] as $c ) {
            $this->assertSame( $c['host'], TrackWP_License::normalize_host( $c['input'] ), wp_json_encode( $c['input'] ) );
        }
    }

    // --- tracking_allowed --------------------------------------------

    public function test_no_license_blocks() {
        $this->assertFalse( TrackWP_License::tracking_allowed() );
    }

    public function test_active_token_allows_until_exp_plus_skew() {
        $this->store( $this->token( 'active' ) );
        $exp = $this->fx['cases'][0]['expect']['exp'];
        $this->assertTrue( TrackWP_License::tracking_allowed( $exp ) );
        $this->assertTrue( TrackWP_License::tracking_allowed( $exp + 299 ) );
        $this->assertFalse( TrackWP_License::tracking_allowed( $exp + 301 ) );
    }

    public function test_token_for_another_host_blocks() {
        $this->store( $this->token( 'active' ) );
        $this->assertTrue( TrackWP_License::tracking_allowed( $this->fx['now'] ) );
        remove_filter( 'pre_option_home', array( $this, 'home_filter' ) );
        $this->assertFalse( TrackWP_License::tracking_allowed( $this->fx['now'] ) );
    }

    public function test_signed_negative_status_blocks() {
        foreach ( array( 'disabled', 'expired', 'unknown', 'limit' ) as $name ) {
            $this->store( $this->token( $name ) );
            $this->assertFalse( TrackWP_License::tracking_allowed( $this->fx['now'] ), $name );
        }
    }

    public function test_forged_and_unknown_kid_tokens_do_not_allow() {
        foreach ( array( 'forged_status', 'unknown_kid', 'garbage', 'empty' ) as $name ) {
            $this->store( $this->token( $name ) );
            $this->assertFalse( TrackWP_License::tracking_allowed( $this->fx['now'] ), $name );
        }
    }

    public function test_grace_period_allows_then_expires() {
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        $this->assertTrue( TrackWP_License::tracking_allowed() );
        update_option( TrackWP_License::GRACE_OPT, time() - 1 );
        $this->assertFalse( TrackWP_License::tracking_allowed( time() ) );
    }

    public function test_grace_ends_on_signed_decision_but_not_on_unknown() {
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        foreach ( array( 'disabled', 'expired', 'limit' ) as $name ) {
            $this->store( $this->token( $name ), '' );
            $this->assertFalse( TrackWP_License::tracking_allowed( $this->fx['now'] ), $name );
        }
        $this->store( $this->token( 'unknown' ), '' );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ), 'unknown' );
        $this->store( $this->token( 'forged_status' ), '' );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ), 'forged_status' );
    }

    public function test_grace_still_allows_without_key_or_without_token() {
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ), 'no option at all' );
        $this->store( '', '' );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ), 'empty key and token' );
        $this->store( '', 'TWP-TEST' );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ), 'key but no token yet' );
    }

    // --- host ----------------------------------------------------------

    public function test_host_ignores_home_url_filters() {
        $this->assertSame( 'example.dk', TrackWP_License::host() );
        add_filter(
            'home_url',
            function () {
                return 'https://da.other.example';
            }
        );
        $this->assertSame( 'example.dk', TrackWP_License::host() );
        remove_all_filters( 'home_url' );
    }

    // --- maybe_refresh -------------------------------------------------

    // maybe_refresh() schedules the recurring check (key or not), so the
    // schedule shows whether it ran.
    public function test_maybe_refresh_runs_for_an_administrator() {
        wp_set_current_user( self::factory()->user->create( array( 'role' => 'administrator' ) ) );
        $this->store( $this->token( 'active' ) );
        wp_clear_scheduled_hook( TrackWP_License::CRON_HOOK );
        TrackWP_License::maybe_refresh();
        $this->assertNotFalse( wp_next_scheduled( TrackWP_License::CRON_HOOK ) );
    }

    public function test_maybe_refresh_schedules_without_a_key() {
        wp_set_current_user( self::factory()->user->create( array( 'role' => 'administrator' ) ) );
        delete_option( TrackWP_License::OPTION );
        $this->mock_http( $this->token_answer( 'active' ) );
        wp_clear_scheduled_hook( TrackWP_License::CRON_HOOK );
        TrackWP_License::maybe_refresh();
        $this->assertNotFalse( wp_next_scheduled( TrackWP_License::CRON_HOOK ) );
        $this->assertSame( 1, $this->mock, 'no valid token: checks at once' );
        wp_clear_scheduled_hook( TrackWP_License::CRON_HOOK );
    }

    public function test_maybe_refresh_skips_ajax_and_users_without_manage_options() {
        $this->store( $this->token( 'active' ) );
        wp_clear_scheduled_hook( TrackWP_License::CRON_HOOK );
        wp_set_current_user( self::factory()->user->create( array( 'role' => 'subscriber' ) ) );
        TrackWP_License::maybe_refresh();
        $this->assertFalse( wp_next_scheduled( TrackWP_License::CRON_HOOK ), 'subscriber' );
        wp_set_current_user( self::factory()->user->create( array( 'role' => 'administrator' ) ) );
        add_filter( 'wp_doing_ajax', '__return_true' );
        TrackWP_License::maybe_refresh();
        remove_filter( 'wp_doing_ajax', '__return_true' );
        $this->assertFalse( wp_next_scheduled( TrackWP_License::CRON_HOOK ), 'ajax' );
        wp_clear_scheduled_hook( TrackWP_License::CRON_HOOK );
    }

    public function test_decision_is_cached_per_request() {
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        $this->assertTrue( TrackWP_License::tracking_allowed() );
        delete_option( TrackWP_License::GRACE_OPT );
        $this->assertTrue( TrackWP_License::tracking_allowed(), 'cached for the rest of the request' );
        TrackWP_License::force_state_for_tests( null );
        $this->assertFalse( TrackWP_License::tracking_allowed() );
    }

    public function test_force_state_for_tests() {
        TrackWP_License::force_state_for_tests( true );
        $this->assertTrue( TrackWP_License::tracking_allowed() );
        TrackWP_License::force_state_for_tests( false );
        $this->assertFalse( TrackWP_License::tracking_allowed() );
    }

    // --- network behaviour -------------------------------------------

    public function network_failures() {
        return array(
            'wp_error'     => array( new WP_Error( 'http_request_failed', 'timeout' ) ),
            'http_429'     => array( self::http( 429, '{"error":"rate_limited"}' ) ),
            'http_500'     => array( self::http( 500, 'oops' ) ),
            'invalid_json' => array( self::http( 200, 'not json{' ) ),
            'no_token'     => array( self::http( 200, '{"x":1}' ) ),
            'bad_token'    => array( self::http( 200, '{"token":"x.y"}' ) ),
        );
    }

    /**
     * @dataProvider network_failures
     */
    public function test_failures_do_not_change_stored_state( $response ) {
        $this->store( $this->token( 'active' ) );
        $before = get_option( TrackWP_License::OPTION );
        $this->mock_http( $response );
        $this->assertWPError( TrackWP_License::check() );
        $this->assertSame( 1, $this->mock );
        $after = get_option( TrackWP_License::OPTION );
        $this->assertSame( $before['token'], $after['token'] );
        $this->assertSame( $before['key'], $after['key'] );
        $this->assertNotSame( '', $after['last_error'] );
        $this->assertTrue( TrackWP_License::tracking_allowed( $this->fx['now'] ) );
    }

    public function test_forged_and_unknown_kid_answers_are_rejected() {
        foreach ( array( 'forged_status', 'unknown_kid' ) as $name ) {
            $this->store( $this->token( 'active' ) );
            $this->mock_http( $this->token_answer( $name ) );
            $this->assertWPError( TrackWP_License::check(), $name );
            $this->assertSame( $this->token( 'active' ), get_option( TrackWP_License::OPTION )['token'], $name );
        }
    }

    public function test_answer_signed_for_another_host_is_rejected() {
        $this->store( $this->token( 'active' ) );
        $this->mock_http( $this->token_answer( 'active' ) );
        remove_filter( 'pre_option_home', array( $this, 'home_filter' ) );
        $this->assertWPError( TrackWP_License::check() );
        $this->assertSame( $this->token( 'active' ), get_option( TrackWP_License::OPTION )['token'] );
    }

    public function test_only_a_signed_negative_answer_blocks() {
        $this->store( $this->token( 'active' ) );
        $this->mock_http( $this->token_answer( 'disabled' ) );
        $this->assertSame( array( 'status' => 'disabled' ), TrackWP_License::check() );
        $this->assertSame( $this->token( 'disabled' ), get_option( TrackWP_License::OPTION )['token'] );
        $this->assertFalse( TrackWP_License::tracking_allowed( $this->fx['now'] ) );
    }

    public function test_check_without_key_sends_domain_only() {
        $seen = array();
        $this->mock = 0;
        add_filter(
            'pre_http_request',
            function ( $pre, $args, $url ) use ( &$seen ) {
                $this->mock++;
                $seen = array( 'args' => $args, 'url' => $url );
                return $this->token_answer( 'active' );
            },
            10,
            3
        );
        $this->assertSame( array( 'status' => 'active' ), TrackWP_License::check() );
        $this->assertSame( 1, $this->mock );
        $this->assertSame( '/check', substr( $seen['url'], -6 ) );
        $this->assertArrayNotHasKey( 'Authorization', $seen['args']['headers'] );
        $body = json_decode( $seen['args']['body'], true );
        $this->assertSame( 'example.dk', $body['domain'] );
        $this->assertTrue( TrackWP_License::tracking_allowed( $this->fx['now'] ) );
    }

    public function test_check_request_matches_contract_fixture() {
        $seen = array();
        add_filter(
            'pre_http_request',
            function ( $pre, $args, $url ) use ( &$seen ) {
                $seen = array( 'args' => $args, 'url' => $url );
                return $this->token_answer( 'active' );
            },
            10,
            3
        );
        TrackWP_License::check();
        $fx = self::fixture( 'check-request.json' );

        $this->assertSame( $fx['method'], $seen['args']['method'] );
        $this->assertSame( 'POST', $seen['args']['method'] );
        $this->assertSame( $fx['path'], substr( wp_parse_url( $seen['url'], PHP_URL_PATH ), -strlen( $fx['path'] ) ) );
        $this->assertSame( '/check', substr( wp_parse_url( $seen['url'], PHP_URL_PATH ), -6 ) );
        $this->assertSame( $fx['headers']['Content-Type'], $seen['args']['headers']['Content-Type'] );
        $this->assertSame( 'application/json', $seen['args']['headers']['Content-Type'] );
        $this->assertArrayNotHasKey( 'Authorization', $seen['args']['headers'] );

        $body = json_decode( $seen['args']['body'], true );
        $keys = array_keys( $body );
        $fx_keys = array_keys( $fx['body'] );
        sort( $keys );
        sort( $fx_keys );
        $this->assertSame( array( 'domain', 'plugin_version', 'wp_version' ), $keys );
        $this->assertSame( $fx_keys, $keys );
        $this->assertSame( 'example.dk', $body['domain'] );
        $this->assertSame( $fx['body']['domain'], $body['domain'] );
    }

    public function test_check_with_stored_key_still_sends_bearer() {
        $this->store( '', 'TWP-OLDKEY' );
        $seen = array();
        add_filter(
            'pre_http_request',
            function ( $pre, $args ) use ( &$seen ) {
                $seen = $args;
                return $this->token_answer( 'active' );
            },
            10,
            2
        );
        TrackWP_License::check();
        $this->assertSame( 'Bearer TWP-OLDKEY', $seen['headers']['Authorization'] );
    }

    public function test_check_in_grace_ends_grace_on_a_signed_decision_only() {
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        $this->mock_http( $this->token_answer( 'unknown' ) );
        $this->assertSame( array( 'status' => 'unknown' ), TrackWP_License::check() );
        $this->assertGreaterThan( 0, TrackWP_License::grace_until(), 'unknown keeps grace' );
        $this->assertTrue( TrackWP_License::tracking_allowed( time() ) );

        $this->mock_http( $this->token_answer( 'active' ) );
        TrackWP_License::check();
        $this->assertSame( 0, TrackWP_License::grace_until(), 'active removes grace' );
        $this->assertTrue( TrackWP_License::tracking_allowed( $this->fx['now'] ) );

        delete_option( TrackWP_License::OPTION );
        update_option( TrackWP_License::GRACE_OPT, time() + 1000 );
        $this->mock_http( $this->token_answer( 'disabled' ) );
        TrackWP_License::check();
        $this->assertSame( 0, TrackWP_License::grace_until(), 'disabled removes grace' );
        $this->assertFalse( TrackWP_License::tracking_allowed( time() ) );
    }

    public function test_cron_check_runs_without_key() {
        $this->mock_http( $this->token_answer( 'active' ) );
        TrackWP_License::cron_check();
        $this->assertSame( 1, $this->mock );
        $this->assertSame( $this->token( 'active' ), get_option( TrackWP_License::OPTION )['token'] );
    }

    public function test_render_page_has_no_key_field() {
        wp_set_current_user( self::factory()->user->create( array( 'role' => 'administrator' ) ) );
        ob_start();
        TrackWP_License::render_page();
        $html = ob_get_clean();
        $this->assertStringNotContainsString( 'license_key', $html );
        $this->assertStringNotContainsString( 'trackwp_license_activate', $html );
        $this->assertStringNotContainsString( 'trackwp_license_deactivate', $html );
        $this->assertStringContainsString( 'trackwp_license_check', $html );
        $this->assertStringContainsString( 'example.dk', $html );
    }

    public function test_update_checker_callbacks() {
        $this->store( $this->token( 'active' ), 'TWP-BBBB' );
        $q = TrackWP_License::puc_query_args( array( 'a' => '1' ) );
        $this->assertSame( 'example.dk', $q['domain'] );
        $h = TrackWP_License::puc_http_args( array( 'timeout' => 5 ) );
        $this->assertSame( 'Bearer TWP-BBBB', $h['headers']['Authorization'] );
        delete_option( TrackWP_License::OPTION );
        $this->assertArrayNotHasKey( 'headers', TrackWP_License::puc_http_args( array() ) );
    }
}
